['flamewheel','sacredfire','steameruption','burnup','pyroball','scorchingsands','flareblitz','fusionflare','scald'].forEach(id=>{ if(MOVES[id]) MOVES[id].thawsUser = true; });

function moveObj(id){ return MOVES[id]; }

